s=s[:i]+'''interface Order {
  id: string;
  priority: boolean;
  line: number;
  items: Map<string, number>;
}

const ORDER_LINE = /^ORDER +([A-Za-z0-9-]+)( +!)?$/;
const ITEM_LINE = /^([A-Z0-9-]+) +x([1-9][0-9]*)$/;

function parseOrders(ordersText: string): Order[] {
  const orders: Order[] = [];
  const seenIds = new Set<string>();
  let current: Order | null = null;

  // Throws at the earliest problem: an empty order is reported at its ORDER
  // line, which always precedes anything found after it.
  const closeCurrent = () => {
    if (current && current.items.size === 0) {
      throw new OrderFormatError(current.line, `order ${current.id} has no items`);
    }
  };

  const lines = ordersText.split("\\n");
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1;
    const line = lines[i]!.trim();
    if (line === "" || line.startsWith("#")) continue;

    const orderMatch = ORDER_LINE.exec(line);
    if (orderMatch) {
      closeCurrent();
      const id = orderMatch[1]!;
      if (seenIds.has(id)) throw new OrderFormatError(lineNo, `duplicate order id ${id}`);
      seenIds.add(id);
      current = { id, priority: orderMatch[2] !== undefined, line: lineNo, items: new Map() };
      orders.push(current);
      continue;
    }

    const itemMatch = ITEM_LINE.exec(line);
    if (itemMatch) {
      if (!current) throw new OrderFormatError(lineNo, "item line before the first ORDER line");
      const sku = itemMatch[1]!;
      current.items.set(sku, (current.items.get(sku) ?? 0) + Number(itemMatch[2]));
      continue;
    }

    closeCurrent();
    throw new OrderFormatError(lineNo, `unrecognized line: ${line}`);
  }
  closeCurrent();
  return orders;
}

function compareLots(a: StockLot, b: StockLot): number {
  if (a.expires !== b.expires) {
    if (a.expires === null) return 1;
    if (b.expires === null) return -1;
    return a.expires < b.expires ? -1 : 1;
  }
  if (a.bin !== b.bin) return a.bin < b.bin ? -1 : 1;
  return 0;
}

function parseBin(bin: string): { aisle: string; rack: number; level: number } {
  const [aisle = "", rack = "", level = ""] = bin.split("-");
  return { aisle, rack: Number(rack), level: Number(level) };
}

function sortByWalk(picks: Pick[]): Pick[] {
  const parsed = picks.map((pick, index) => ({ pick, index, ...parseBin(pick.bin) }));
  const aisles = [...new Set(parsed.map((p) => p.aisle))].sort();
  const descending = new Set(aisles.filter((_, i) => i % 2 === 1));
  parsed.sort((a, b) => {
    if (a.aisle !== b.aisle) return a.aisle < b.aisle ? -1 : 1;
    if (a.rack !== b.rack) return descending.has(a.aisle) ? b.rack - a.rack : a.rack - b.rack;
    if (a.level !== b.level) return a.level - b.level;
    if (a.pick.bin !== b.pick.bin) return a.pick.bin < b.pick.bin ? -1 : 1;
    return a.index - b.index;
  });
  return parsed.map((p) => p.pick);
}

export function buildPickList(ordersText: string, stock: StockLot[]): PickList {
  const orders = parseOrders(ordersText);
  const served = [...orders.filter((o) => o.priority), ...orders.filter((o) => !o.priority)];

  // Working copies so the caller's stock stays untouched.
  const lotsBySku = new Map<string, { lot: StockLot; left: number }[]>();
  for (const lot of stock) {
    let lots = lotsBySku.get(lot.sku);
    if (!lots) lotsBySku.set(lot.sku, (lots = []));
    lots.push({ lot, left: lot.qty });
  }
  for (const lots of lotsBySku.values()) lots.sort((a, b) => compareLots(a.lot, b.lot));

  const picks: Pick[] = [];
  const shortages: Shortage[] = [];
  for (const order of served) {
    for (const [sku, qty] of order.items) {
      let needed = qty;
      for (const entry of lotsBySku.get(sku) ?? []) {
        if (needed === 0) break;
        if (entry.left <= 0) continue;
        const taken = Math.min(entry.left, needed);
        entry.left -= taken;
        needed -= taken;
        picks.push({ bin: entry.lot.bin, sku, qty: taken, orderId: order.id });
      }
      if (needed > 0) shortages.push({ orderId: order.id, sku, missing: needed });
    }
  }

  return { picks: sortByWalk(picks), shortages };
}
'''
open(p,'w').write(s)
EOF

cat >> src/pickList.test.ts <<'EOF'

import { buildPickList, type StockLot } from "./pickList";

const lot = (bin: string, sku: string, qty: number, expires: string | null = null): StockLot => ({ bin, sku, qty, expires });

function lineOf(text: string): number {
  try {
    buildPickList(text, []);
  } catch (e) {
    if (e instanceof OrderFormatError) return e.line;
    throw e;
  }
  throw new Error("no error");
}

test("example: FEFO allocation, priority first, shortages", () => {
  const text = "# export 2026-10-12 06:00\nORDER 1001\n  OLIVE-500 x3\n  PASTA-1KG x1\nORDER 1002 !\n  OLIVE-500 x2\n";
  const stock = [
    lot("B-01-1", "OLIVE-500", 2, "2027-01-01"),
    lot("A-02-1", "OLIVE-500", 1, "2026-11-01"),
    lot("A-05-1", "OLIVE-500", 10, null),
  ];
  const snapshot = JSON.parse(JSON.stringify(stock));
  const result = buildPickList(text, stock);
  expect(stock).toEqual(snapshot);
  expect(result.shortages).toEqual([{ orderId: "1001", sku: "PASTA-1KG", missing: 1 }]);
  expect(result.picks).toEqual([
    { bin: "A-02-1", sku: "OLIVE-500", qty: 1, orderId: "1002" },
    { bin: "A-05-1", sku: "OLIVE-500", qty: 2, orderId: "1001" },
    { bin: "B-01-1", sku: "OLIVE-500", qty: 1, orderId: "1002" },
    { bin: "B-01-1", sku: "OLIVE-500", qty: 1, orderId: "1001" },
  ]);
});

test("duplicate SKUs are summed; partial shortage", () => {
  const r = buildPickList("ORDER a\nX x2\nY x1\nX   x3", [lot("A-01-1", "X", 4), lot("A-01-2", "Y", 1)]);
  expect(r.shortages).toEqual([{ orderId: "a", sku: "X", missing: 1 }]);
  expect(r.picks.map((p) => [p.bin, p.qty])).toEqual([["A-01-1", 4], ["A-01-2", 1]]);
});

test("serpentine walk over aisles with picks", () => {
  const stock = ["A-01-2", "A-03-1", "C-01-1", "C-04-1", "C-04-2", "D-02-1", "D-01-1"].map((b, i) => lot(b, `S${i}`, 1));
  const text = "ORDER o\n" + stock.map((l) => `${l.sku} x1`).join("\n");
  const bins = buildPickList(text, stock).picks.map((p) => p.bin);
  expect(bins).toEqual(["A-01-2", "A-03-1", "C-04-1", "C-04-2", "C-01-1", "D-01-1", "D-02-1"]);
});

test("format errors", () => {
  expect(lineOf("\nX x1\nORDER 1\nX x1")).toBe(2);
  expect(lineOf("ORDER 1\nX x1\nORDER 1\nX x1")).toBe(3);
  expect(lineOf("ORDER 1\n# c\nORDER 2\nX x1")).toBe(1);
  expect(lineOf("ORDER 1\nX x1\nORDER 2")).toBe(3);
  expect(lineOf("ORDER 1\nORDER 1\nX x1")).toBe(1);
  expect(lineOf("ORDER 1\nX x0")).toBe(2);
  expect(lineOf("ORDER 1\nX x03")).toBe(2);
  expect(lineOf("ORDER 1\nx-a x3")).toBe(2);
  expect(lineOf("ORDER 1\nX 3")).toBe(2);
  expect(lineOf("ORDER 1!\nX 3")).toBe(1);
  expect(buildPickList("ORDER 1   !\nX x1", []).shortages).toEqual([{ orderId: "1", sku: "X", missing: 1 }]);
});
EOF
